                      TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).
  Notation X4F' mm spl bd4 := (X4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm spl bd4).

  (* [comment removed for export] *)
  Variables (O2 L2 Q2 v24 v32 v48 v56 v64 v96 v120 v128 v144 v152 c4 bc4 ptr4 st4 : Z) (j0 j72 j88 j104 jp : list byte).
  Variables (y10 y12 y15 y22 y23 : word).
  Hypothesis HL2 : 6 <= O2 /\ 1 <= L2 /\ O2 + L2 <= n.
  Hypothesis HQ2 : 0 < Q2 <= dcap.
  Notation SPL := (SPL3 v24 v32 (tl + 256 * mtl) v48 v56 v64 (DST + Q2) v96 v120 v128 (SS + O2 + 8) v144 v152 j0 j72 j88 j104).
  Notation BD := (BD4 c4 bc4 ptr4 st4 jp).

